/**
 * B2C oturum (auth cookie) yardımcıları — tek kaynak.
 *
 * Login'de yazılan tüm cookie'lerin listesi ve logout davranışı burada toplanır;
 * hem manuel logout (header) hem de geçersiz token'da otomatik logout (apiClient)
 * aynı listeyi ve aynı reload davranışını kullanır.
 *
 * İki token tutulur: `auth-token` (api_token/token_old → legacy api + apiv2) ve
 * `auth-token-v3` (Sanctum → apiv3). Yalnızca tarayıcıda anlamlıdır (cookie'ler
 * JS-okunur, httpOnly değil).
 */
import { deleteCookie, getCookie } from "cookies-next";

/** Login'de yazılan auth/profil cookie'lerinin tamamı (bkz. auth/login/page.tsx). */
export const AUTH_COOKIES = [
  "auth-token",
  "auth-token-v3",
  "user-email",
  "user-avatar",
  "user-full-name",
  "user-id",
  "user-role",
] as const;

/** Tüm auth cookie'lerini siler (yönlendirme/reload yapmaz). */
export function clearAuthCookies(): void {
  AUTH_COOKIES.forEach((name) => deleteCookie(name));
}

/** Kullanıcı kendini login'li sanıyor mu? (en az bir token cookie'si var) */
export function hasAuthCookie(): boolean {
  return Boolean(getCookie("auth-token-v3") || getCookie("auth-token"));
}

/**
 * Oturumu zorla kapat: tüm auth cookie'lerini silip sayfayı sessizce reload eder
 * (kullanıcı bulunduğu sayfada kalır, artık logout durumunda). Token geçersiz/süresi
 * dolmuş veya hesap disable edilmişse (401) ve manuel Logout'ta kullanılır.
 * Yalnızca tarayıcıda çağrılmalıdır.
 *
 * İdempotent: tek bir sayfa yüklemesinde birden çok 401 (örn. tur detayda paralel
 * fiyat/availability/yorum istekleri) art arda gelse bile reload yalnızca bir kez
 * tetiklenir.
 */
let loggingOut = false;
export function forceLogout(): void {
  if (typeof window === "undefined" || loggingOut) return;
  loggingOut = true;
  clearAuthCookies();
  window.location.reload();
}

/** Zorla logout başladı mı? (reload yolda — yeni hata fırlatmanın anlamı yok) */
export function isLoggingOut(): boolean {
  return loggingOut;
}

/**
 * Logout başladığında çağıranı SESSİZCE askıya alır: asla resolve/reject etmeyen
 * bir promise döner. Reload (~ms) gelene kadar hiçbir hata fırlatılmaz, hiçbir
 * unhandled-rejection oluşmaz ve çağıran bozuk veriyle ilerlemez → Sentry'e gürültü
 * düşmez, "Unhandled Runtime Error" overlay'i çakmaz. Stabil logout'un anahtarı budur.
 */
export function haltForLogout<T = never>(): Promise<T> {
  return new Promise<T>(() => {});
}

/** İstek bizim apiv3/apiv2 tarayıcı proxy'lerimize mi gidiyor? (3p analytics/gtm hariç) */
function isApiProxyRequest(input: RequestInfo | URL): boolean {
  let raw = "";
  if (typeof input === "string") raw = input;
  else if (input instanceof URL) raw = input.pathname;
  else if (typeof Request !== "undefined" && input instanceof Request) raw = input.url;
  let path = raw;
  try {
    if (/^https?:\/\//i.test(raw)) path = new URL(raw).pathname;
  } catch {
    path = raw;
  }
  return path.startsWith("/api/apiv2") || path.startsWith("/api/apiv3");
}

/**
 * Tüm tarayıcı fetch'lerini saran TEK SEFERLİK global interceptor.
 *
 * apiClient'ın kendi 401 guard'ı yalnızca apiClient'tan geçen istekleri korur; oysa
 * tsbnext'te hâlâ apiClient'tan GEÇMEYEN ham fetch'ler var (apiv2 fiyat/availability/
 * pricemonths/search, tur listeleme...). Bunlar operatörde `auth-token-v3`'ü Bearer
 * gönderir; token geçersizse 401 "Unauthenticated." döner ama eskiden hiçbir logout
 * tetiklenmezdi (ham fetch hatayı yutuyordu, ekran "Loading..."ta takılıyordu).
 *
 * Bu interceptor window.fetch'i tek sefer sarar: bizim apiv3/apiv2 proxy uçlarımızdan
 * 401 dönen HER istekte (kaynağı apiClient olsun ya da ham fetch) login'li kullanıcıyı
 * (cookie var) zorla logout eder. Yol filtresi 3p istekleri (analytics/gtm) dışarıda
 * tutar; anonim kullanıcı (cookie yok) tetiklemez → reload döngüsü olmaz.
 *
 * Render fazında (useEffect değil) çağrılır ki çocuk bileşenlerin effect'lerindeki
 * fetch'ler ateşlenmeden önce kurulmuş olsun.
 */
let interceptorInstalled = false;
export function installAuthInterceptor(): void {
  if (typeof window === "undefined" || interceptorInstalled) return;
  interceptorInstalled = true;
  const originalFetch = window.fetch.bind(window);
  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const isApi = isApiProxyRequest(input);

    // Logout zaten başladıysa yeni isteği hiç başlatma — sessizce askıya al (reload yolda).
    if (loggingOut && isApi) return haltForLogout<Response>();

    const res = await originalFetch(input as any, init);
    if (!isApi) return res;

    // İlk 401 (cookie hâlâ varken) logout'u tetikler.
    if (res.status === 401 && hasAuthCookie()) {
      forceLogout();
      return haltForLogout<Response>();
    }
    // YARIŞ KORUMASI: ilk 401 forceLogout'u tetikleyip cookie'leri SİLDİKTEN sonra,
    // eşzamanlı uçuştaki diğer 401'ler artık hasAuthCookie()=false görür. Onları da
    // (ve logout sürerken dönen başka her yanıtı) sessizce askıya al ki çağırana 401
    // gövdesi dönüp .json()/throw etmesin → "2 errors" tam olarak buradan çıkıyordu.
    if (loggingOut) return haltForLogout<Response>();

    return res;
  };
}
